def photo(asset):return f'<figure class="photo"><img src="assets/{str(Path(asset).with_suffix('.webp'))}" alt="Existing illustrative service image; not completed P1 work"><figcaption>Existing service illustration · not a completed P1 project</figcaption></figure>'
def button(text='Request a site visit',dest='quote.html'):return f'<a class="button" href="{dest}">{text} →</a>'
def section(label,title,body):return f'<section class="section"><span class="eyebrow">{label}</span><h2>{title}</h2>{body}</section>'
def rows(items=SERVICES):return ''.join(f'<a class="index-row" href="{s[0]}.html"><small>{i+1:02}</small><strong>{s[1]}</strong><span>{s[3]}</span><b>↗</b></a>' for i,s in enumerate(items))
def cards(items):return '<div class="grid">'+''.join(f'<a class="proof-card" href="{s[0]}.html">{photo(s[2])}<h3>{s[1]}</h3><p>{s[3]}</p><span>Explore scope →</span></a>'for s in items)+'</div>'
def sequence(items):return '<div class="timeline">'+''.join(f'<article><div><h3>{t}</h3><p>{b}</p></div></article>'for t,b in items)+'</div>'
def hero(label,title,desc,asset=None):
 if CURRENT_DIRECTION=='b' and asset:
  return '<section class="hero"><div class="split"><div><span class="eyebrow">'+label+'</span><h1>'+title+'</h1><p>'+desc+'</p><div class="actions">'+button()+'<a href="services.html">Review scope →</a></div></div><aside class="aside"><span class="eyebrow">Field of work</span><h3>Land & site</h3><p>Clearing · Grading · Reconstruction</p><h3>Water</h3><p>Drainage · Ponds · Erosion</p><h3>Ongoing care</h3><p>Grounds · Vegetation · Seasonal needs</p></aside></div><div class="rail"><span>1-acre-plus working properties</span><span>Upstate SC + Greater Charlotte</span><span>Scope and schedule agreed before work</span></div><div class="wide section">'+photo(asset)+'</div></section>'
 return '<section class="hero"><span class="eyebrow">'+label+'</span>'+('<div class="split">' if asset else '')+f'<div><h1>{title}</h1><p>{desc}</p><div class="actions">{button()}<a href="services.html">Explore capabilities →</a></div></div>'+ (photo(asset)+'</div>' if asset else '')+'<div class="rail"><span>Properties of an acre or more</span><span>Upstate South Carolina + Greater Charlotte</span><span>Land · Water · Ongoing care</span></div></section>'
BASE_PROCESS=[('Walk the property','Review the need, access, water movement and intended land use together.'),('Agree the scope','Identify the work, order, responsibilities and any specialist approvals.'),('Plan the work','Confirm scheduling, equipment access and communication before starting.'),('Review the result','Discuss completion against the agreed scope and any ongoing care.')]
def faqs(items):return ''.join(f'<details><summary>{q}</summary><p>{a}</p></details>'for q,a in items)
def quote():return '''<div class="sidebar"><form class="form" action="confirmation.html" method="get" onsubmit="event.preventDefault();location.href='confirmation.html'"><p class="notice">Local design simulation. Nothing is sent to P1. Use sample details only.</p><fieldset><legend>What does your property need?</legend>'''+''.join(f'<label class="radio"><input type="radio" name="need" value="{v}" required>{v}</label>' for v in ['Ongoing commercial care','Clearing, grading or drainage','Farm or large acreage','Pond or waterway','Snow and ice','Not sure yet'])+'''</fieldset><label class="field">Your name (required)<input required autocomplete="name"></label><label class="field">Email (required)<input type="email" required autocomplete="email"></label><label class="field">Phone (optional)<input type="tel" autocomplete="tel"></label><label class="field">Property address or city (required)<input required></label><label class="field">What needs attention? (required)<textarea required rows="4" placeholder="Tell us what you see and what you want to change."></textarea></label><details><summary>Add property details (optional)</summary><label class="field">Company<input autocomplete="organization"></label><label class="field">Approximate acreage<select><option>Not sure yet</option><option>Under 1 acre</option><option>1–5 acres</option><option>5–20 acres</option><option>20–100 acres</option><option>100+ acres</option></select></label><label class="field">Timing<select><option>Planning ahead</option><option>Within 30 days</option><option>1–3 months</option></select></label></details><p class="muted">We use inquiry details to review your property and follow up. Avoid access codes or sensitive information. Photo upload is a future option, subject to support and privacy review.</p><button class="button" type="submit">Preview confirmation →</button><p><a href="form-error.html">View proposed error state</a></p></form><aside class="aside"><span class="eyebrow">What happens next</span><h2>A conversation, then a site walk.</h2>'''+sequence(BASE_PROCESS[:3])+'''<p>Fit, scope and appointment times are confirmed by P1. An inquiry is not a booked visit.</p><a href="tel:+17042218928">Call (704) 221-8928</a></aside></div>'''
def proof_template():return hero('Proof architecture · template only','The property. The problem. The work.','A project profile should explain how P1 approached a real property. No completed project facts have been verified for this mockup.','service-reconstruction-smaller-scale.png')+section('Project facts','Verified facts belong here.','<div class="facts">'+''.join(f'<div><small>{x}</small><strong>Pending verification</strong></div>'for x in ['Property type','Location','Scope','Outcome'])+'</div><p class="notice">This image is an illustration. It does not establish a project, acreage, completion date, equipment ownership or customer result.</p>')+section('Project narrative','From problem to result.',sequence([('Problem','Owner-approved description and before photos required.'),('Work performed','Verified scope, sequence and actual equipment used required.'),('Result','Matched after photos and a supportable outcome required.')]))+section('Supporting evidence','A record of the work.','<div class="columns">'+''.join('<div>'+photo(s[2])+f'<h3>{t}</h3><p>Replace with approved photographs from this same project.</p></div>' for s,t in zip([S['land-clearing'],S['grading-site-preparation'],S['drainage']],['Before','During','After']))+'</div>')
def gallery():return hero('Capability illustrations + future project proof','See the work in context.','Compare service categories. Verified project stories will be a separate collection, with actual scope, location and results.')+section('Browse capabilities','Start with the need.','<div class="filters" aria-label="Service filters">'+''.join(f'<button type="button" aria-pressed="{str(v=="all").lower()}" onclick="document.querySelectorAll(\'.gallery-item\').forEach(e=>e.hidden=\'{v}\'!==\'all\'&&e.dataset.kind!==\'{v}\');this.parentElement.querySelectorAll(\'button\').forEach(b=>b.setAttribute(\'aria-pressed\',b===this));document.getElementById(\'count\').textContent=document.querySelectorAll(\'.gallery-item:not([hidden])\').length+\' illustrations shown\'">{title}</button>'for v,title in [('all','All'),('land','Land & site'),('water','Water'),('grounds','Ongoing care'),('vegetation','Vegetation')])+'</div><p id="count" role="status">10 illustrations shown</p><div class="grid">'+''.join(f'<a data-kind="{s[4]}" class="gallery-item proof-card" href="{s[0]}.html">{photo(s[2])}<h3>{s[1]}</h3><span>Scope and next steps →</span></a>'for s in SERVICES)+'</div>')+section('Separate proof collection','Project profiles need real evidence.','<p>Service and property-type filters become meaningful when a verified project collection exists. Do not classify an illustration as a commercial, HOA or agricultural P1 job.</p>'+button('Review project profile template','project-profile.html'))
def home(direction):
 titles={'a':'Land. Water.<br>Groundwork.','b':'One property.<br>One clear plan.','c':'A better future<br>for your land.','r':'Land specialists.<br>From groundwork<br>to ongoing care.'}
 return hero('P1 Land & Property Management',titles[direction],'Clearing, grading, drainage and ongoing care for working properties of an acre or more. Serving Upstate South Carolina and Greater Charlotte.','hero-upstate-cities.png')+section('01 · Land is the starting point','What does your property need?',rows([S['land-clearing'],S['grading-site-preparation'],S['drainage'],S['commercial-landscaping']]))+section('02 · Work in context','Capability you can see.','<p>These illustrations explain the kinds of work. Authentic project records will show the property, scope and outcome.</p>'+cards([S['grading-site-preparation'],S['pond-waterway-management'],S['property-reconstruction']]))+section('03 · Properties we serve','Working land. Substantial responsibilities.','<div class="columns">'+''.join(f'<div><h3>{t}</h3><p>{b}</p><a href="{dest}">Explore the fit →</a></div>' for t,b,dest in [('Commercial & industrial','Grounds, drainage, access and recurring care.','commercial.html'),('Agricultural & rural','Fields, ponds, brush, access and land improvement.','industrial-agricultural.html'),('Municipal & institutional','Large exterior areas with operational priorities.','services.html')])+'</div><p class="notice">Owner decision: whether estates, HOA common areas and large residential acreage are eligible. Current live copy excludes residential services.</p>')+section('04 · Equipment and process','The right resources for the scope.','<div class="split">'+photo('features/grading-level.png')+'<div><p>Equipment should make the work understandable: shaping ground, moving material, managing vegetation and restoring access.</p><p>Actual fleet ownership, models, operators and capability facts require owner verification.</p>'+sequence(BASE_PROCESS[:2])+'</div></div>')+section('05 · Regional fit','Two regions. One clear starting point.','<div class="columns two"><div><h3>Upstate South Carolina</h3><p>Greenville, Spartanburg, Anderson and surrounding communities.</p><a href="region.html">Explore the region →</a></div><div><h3>Greater Charlotte</h3><p>Charlotte and surrounding NC communities, including SC border counties.</p><a href="location.html">Explore local coverage →</a></div></div>')+section('06 · Customer feedback','Dependability and communication matter.','<p>The live review presentation includes feedback about pond growth cleanup, quality and communication. Link to original reviews and retain source dates; pair a review with project facts only after confirming the connection.</p><a href="testimonials.html">Review the proposed feedback system →</a>')
def service(s):
 slug,title,asset,desc,kind,scope,consider=s
 special=''
 if slug=='drainage':special=section('Water movement','Follow the water before choosing the work.','<div class="model"><strong>Conceptual explanation · not a drainage design</strong><ol><li>Record where runoff enters the property.</li><li>Identify low points, erosion and existing features.</li><li>Discuss possible grading, swales or drainage systems.</li><li>Confirm the outlet, approvals and any specialist responsibilities.</li></ol></div><p>Field photographs taken after rain can help the conversation. The solution depends on actual site conditions.</p>')
 if slug=='grading-site-preparation':special=section('Sequence','Prepare the site in the right order.',sequence([('Review plans and access','Confirm the required grades, scope, tolerances and responsible specialists.'),('Clear and shape','Coordinate clearing, rough grading and material movement.'),('Finish and establish','Prepare agreed grades and drainage before surfaces or turf are established.')]))
 if slug=='commercial-landscaping':special=section('Recurring program','Care that fits the operation.','<div class="columns"><div><h3>Property condition</h3><p>Agree the grounds and vegetation priorities.</p></div><div><h3>Scheduled work</h3><p>Set an appropriate recurring and seasonal scope.</p></div><div><h3>Corrective needs</h3><p>Discuss drainage, erosion and damaged ground alongside upkeep.</p></div></div><a href="commercial.html">Commercial site-management experience →</a>')
 if slug=='land-clearing':special=section('Selective decisions','Open access. Retain what matters.','<p>Distinguish clearing, forestry mulching and tree work. Identify retained vegetation, intended future use, access and material handling during the site walk.</p>')
 if slug=='pond-waterway-management':special=section('Water and edges','A pond is part of a property system.','<p>Look at banks, vegetation, erosion, inlets and outlets. Construction, restoration, maintenance and regulatory responsibilities are different scopes; confirm which applies.</p>')
 if slug=='property-reconstruction':special=section('Coordinated restoration','Solve the cause before restoring the surface.',sequence([('Identify the failure','Understand damaged ground, vegetation, water and access.'),('Coordinate the work','Clear, shape and address water movement in the agreed order.'),('Re-establish the property','Restore intended surfaces and discuss ongoing care.')]))
 related=[x for x in SERVICES if x[4]==kind and x[0]!=slug][:2] or [S['grading-site-preparation'],S['drainage']]
 return hero('Capabilities / '+title,title,desc,asset)+section('Scope','What we can discuss.','<div class="columns">'+''.join(f'<div><small>{i+1:02}</small><h3>{x}</h3><p>Confirm the proposed work, site conditions and delivery responsibilities with P1.</p></div>'for i,x in enumerate(scope))+'</div>')+special+section('Site fit','What matters before work starts.','<div class="split"><div>'+''.join(f'<h3>{x}</h3><p>Bring the available property information and discuss it during qualification.</p>'for x in consider)+'</div>'+photo(asset)+'</div>')+section('How work proceeds','A clear scope before a start date.',sequence(BASE_PROCESS))+section('Evidence','A similar problem deserves a relevant example.','<p>Attach verified P1 project photography and scope here when approved. Until then, this page explains capability without claiming a completed job.</p>'+button('View project-profile structure','project-profile.html'))+section('Decision questions','Before you contact P1.',faqs([('Is my property a fit?','The current site focuses on working properties of an acre or more. Confirm eligibility, exact service coverage and the work needed.'),('What should I bring to a site walk?','An address or city, the issue, intended land use, available plans and useful timing. Do not share sensitive site details.'),('Will specialist review be needed?','Engineering, approvals and specialist involvement depend on the work. Responsibilities belong in the agreed scope.')]))+section('Related work','Keep the whole property in view.',rows(related))
